export const BRUSH_BY_ID: Record<string, BrushPreset> = (() => {
  const m: Record<string, BrushPreset> = {};
  for (const cat of BRUSH_CATEGORIES) {
    for (const b of cat.brushes) m[b.id] = b;
  }
  return m;
})();
